<?php
namespace App\Http\Controllers; use App\Domain\Commerce\Models\Order; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Inertia\Inertia; class AdminCustomersController {public function index(Request $r){$q=Order::query()->select('customer_email',DB::raw('MAX(customer_phone) as customer_phone'),DB::raw('COUNT(*) as orders_count'),DB::raw('SUM(total_amount) as lifetime_value'),DB::raw('MAX(placed_at) as last_order_at'))->groupBy('customer_email')->orderByDesc('last_order_at');if($r->filled('q'))$q->where('customer_email','ilike','%'.$r->q.'%');return Inertia::render('Admin/Customers/Index',['customers'=>$q->paginate(30)->withQueryString()]);}}
